/* Local SVG/CSS process sequence; no frame loop or pointer tracking. */
(()=>{const root=document.querySelector('#creative-process.signal-process');if(!root)return;const words=[...root.querySelectorAll('.signal-word')],nodes=[...root.querySelectorAll('.signal-node')];let visible=false,hover=null,focus=null;function highlight(){const step=hover??focus;words.forEach((w,i)=>w.classList.toggle('is-active',i===step))}nodes.forEach((node,i)=>{node.addEventListener('pointerenter',()=>{hover=i;highlight()});node.addEventListener('pointerleave',()=>{hover=null;highlight()});node.addEventListener('focus',()=>{focus=i;highlight()});node.addEventListener('blur',()=>{focus=null;highlight()})});words.forEach((word,i)=>{word.addEventListener('pointerenter',()=>{hover=i;highlight()});word.addEventListener('pointerleave',()=>{hover=null;highlight()})});root.classList.add('signal-ready');new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)root.classList.add('signal-started');root.classList.toggle('signal-running',visible&&!document.hidden)},{threshold:.18,rootMargin:"-90px 0px 0px 0px"}).observe(root);document.addEventListener('visibilitychange',()=>root.classList.toggle('signal-running',visible&&!document.hidden));})();
